---EnterBattle
------进入战斗时的阴影的设置的逻辑
function XGraphicSetup.EnterBattle()
    FuntoyRenderFeature.planeShadowQuality = FuntoyRenderFeature.PlaneShadowQuality.Low
end

---ExitBattle
---退出战斗时的阴影的还原的逻辑
function XGraphicSetup.ExitBattle()
    local settingJson = PlayerPrefsUtility.GetEncryptedString(CUSTOM_SETTING_PREFS, '')
    local graphicLevel = XGraphicQuality.High
    if string.isEmpty(settingJson) then
        local quality = XGraphicSetup.GetDefaultQuality()
        ---获取硬件设置
        ---@type TableML.TableFile
        local tableFile = SettingModule.Get(SettingGraphicPath)
        ---@type TableML.TableFileRow
        local row = tableFile:GetByPrimaryKey(quality)
        graphicLevel = checkNumber(row:Get('graphicLevel'))
    else
        local setting = table.deserialize(settingJson)
        graphicLevel = checkNumber(setting.graphicLevel)
    end
    print("===== 退出战斗时: " .. graphicLevel .. " =====")
    XGraphicSetup.ApplyPlaneShadowQuality(graphicLevel)
    XGraphicSetup.ApplyReflection(graphicLevel)
    XGraphicSetup.ApplyRoleOutline(graphicLevel)
end




-- SetMaxAdditionalLightsCount
-- 根据玩家设置的 画面等级, 设置 UniversalRP 配置文件中的 Additional Lights - "Per Object Limit" 一值:
-- todo: 目前不关心 原始值 为多少, 也不缓存原始值; 因为目前只有 春节场景中有 点光源这个需求; 未来增加 缓存原始值 这个功能;
---@param lowestCount_     integer @ 推荐 2
---@param lowCount_        integer @ 推荐 4
---@param middleCount_     integer @ 推荐 6
---@param highCount_       integer @ 推荐 8
---@param highestCount_    integer @ 推荐 8
function XGraphicSetup.SetMaxAdditionalLightsCount( lowestCount_, lowCount_, middleCount_, highCount_, highestCount_ )
    local settingJson = PlayerPrefsUtility.GetEncryptedString(CUSTOM_SETTING_PREFS, '')
    local graphicLevel = XGraphicQuality.High
    if string.isEmpty(settingJson) then
        local quality = XGraphicSetup.GetDefaultQuality() -- 根据玩家的设备信息, 自动分配一个最初的 画面等级;
        ---获取硬件设置
        ---@type TableML.TableFile
        local tableFile = SettingModule.Get(SettingGraphicPath)
        ---@type TableML.TableFileRow
        local row = tableFile:GetByPrimaryKey(quality)
        graphicLevel = checkNumber(row:Get('graphicLevel'))
    else
        local setting = table.deserialize(settingJson)
        graphicLevel = checkNumber(setting.graphicLevel)
    end
    ---:
    local lightCount = 2
    if graphicLevel == XGraphicQuality.Lowest then 
        lightCount = lowestCount_
    elseif graphicLevel == XGraphicQuality.Low then
        lightCount = lowCount_
    elseif graphicLevel == XGraphicQuality.Middle then
        lightCount = middleCount_
    elseif graphicLevel == XGraphicQuality.High then
        lightCount = highCount_
    elseif graphicLevel == XGraphicQuality.Highest then
        lightCount = highestCount_
    end
    ---:
    printInfo( "原始 maxAdditionalLightsCount = " .. UniversalRenderPipeline.asset.maxAdditionalLightsCount )
    UniversalRenderPipeline.asset.maxAdditionalLightsCount = lightCount
    printInfo( "修改后 maxAdditionalLightsCount = " .. UniversalRenderPipeline.asset.maxAdditionalLightsCount )
end



function XGraphicSetup.ApplyPlaneShadowQuality(quality)
    if checkNumber(quality) <= XGraphicQuality.Middle then
        FuntoyRenderFeature.planeShadowQuality = FuntoyRenderFeature.PlaneShadowQuality.Low
    else
        FuntoyRenderFeature.planeShadowQuality = FuntoyRenderFeature.PlaneShadowQuality.High
    end
end


-- 当选择最低画质时, 彻底关闭 角色轮廓线
function XGraphicSetup.ApplyRoleOutline(quality)

    local rendererFeature = KTool.GetRenderFeatureActiveByName("NewFuntoyRenderFeature")
    if not isNull(rendererFeature) then
        if checkNumber(quality) == XGraphicQuality.Lowest then
            rendererFeature.roleSettings.ShowOutline = false
            print("~~~~~~ 轮廓线 删除 ~~~~~~"..quality)
        else
            rendererFeature.roleSettings.ShowOutline = true
            print("~~~~~~ 轮廓线 显示 ~~~~~~"..quality)
        end
    end
end

---Apply
---应用图像设置
---@param setting table
function XGraphicSetup.Apply(setting)

    ---画面质量
    QualitySettings.SetQualityLevel(checkNumber(setting.graphicLevel) + 1, true)
    ---阴影
    XGraphicSetup.ApplyShadow(setting.shadowLevel)

    ---分辨率
    ---@type TableML.TableFile
    local resolutionTableFile = SettingModule.Get(SettingResolutionPath)
    local resolutionRow = resolutionTableFile:GetByPrimaryKey(checkNumber(setting.resolutionLevel))
    XGraphicSetup.ApplyResolution({
        scale = checkNumber(resolutionRow:Get("scale")),
        sceneHeight = checkNumber(resolutionRow:Get("sceneHeight"))
    })

    print("===== 应用图像设置: " .. setting.graphicLevel .. " =====")
    ---是否开启反射
    XGraphicSetup.ApplyReflection(checkNumber(setting.graphicLevel))
    ---设置平面阴影
    XGraphicSetup.ApplyPlaneShadowQuality(checkNumber(setting.graphicLevel))
    --- 是否开启角色轮廓线
    XGraphicSetup.ApplyRoleOutline(checkNumber(setting.graphicLevel))

    ---设置fps等级
    XGraphicSetup.ApplyFrameRate(checkNumber(setting.fpsLevel))

    ---抗锯齿
    local antiAliasTableFile = SettingModule.Get(SettingAtiPath)
    local antiAliasRow = antiAliasTableFile:GetByPrimaryKey(checkNumber(setting.fxaaLevel))
    local enable = checkNumber(antiAliasRow:Get('enable'))
    XGraphicSetup.ApplyAntialias({
        enable = enable,
        quality = checkNumber(antiAliasRow:Get('quality'))
    })

    ---材质等级
    local lodTableFile = SettingModule.Get(SettingLODPath)
    local lodRow = lodTableFile:GetByPrimaryKey(checkNumber(setting.lodLevel))
    local lod = checkNumber(lodRow:Get('lod'))
    XGraphicSetup.ApplyLOD(lod)
    ---Bloom信息
    local bloomTableFile = SettingModule.Get(SettingBloomPath)
    local bloomRow = bloomTableFile:GetByPrimaryKey(checkNumber(setting.bloomLevel))
    local enable = checkNumber(bloomRow:Get('enable'))
    XGraphicSetup.ApplyBloom({
        enable = enable,
        blur = checkNumber(bloomRow:Get('blur')),
        blurIteration = checkNumber(bloomRow:Get('blurIteration'))
    })

end

---ApplyGraphic
---设置画面质量的信息
---@param level integer
function XGraphicSetup.ApplyGraphic(level)
    QualitySettings.SetQualityLevel(checkNumber(level) + 1, true)

    print("===== ApplyGraphic: " .. checkNumber(level) .. " =====")
    ---设置平面阴影
    XGraphicSetup.ApplyPlaneShadowQuality(checkNumber(level))
    ---是否开启反射
    XGraphicSetup.ApplyReflection(checkNumber(level))
    --- 是否开启角色轮廓线
    XGraphicSetup.ApplyRoleOutline(checkNumber(level))
end

