---ApplyShadow
---设置阴影的信息,与描边2选一,低端机上     这个函数其实已经无效了...
---@param level integer
function XGraphicSetup.ApplyShadow(level)
    local roleRenderFeature = KTool.GetRenderFeatureActiveByName('NewRoleRenderFeature')
    if checkInt(level) == 0 then
        if not isNull(roleRenderFeature) then
            roleRenderFeature.settings.ShowPlaneShadow = false
        end
    else
        if not isNull(roleRenderFeature) then
            roleRenderFeature.settings.ShowPlaneShadow = true
        end
    end
end

---ApplyLOD
---设置lod的等级
---@param level number
function XGraphicSetup.ApplyLOD(level)
    Shader.globalMaximumLOD = checkNumber(level)
    if checkNumber(level) == 100 then
        ---禁用地面反射
        CS.StylizedWater.PlanarReflections.IsEnable = false
        Shader.EnableKeyword("LOD_100")
    else
        Shader.DisableKeyword("LOD_100")
		CS.StylizedWater.PlanarReflections.IsEnable = true
    end
end

---ApplyBloom
---设置bloom的信息
---@param setting table
function XGraphicSetup.ApplyBloom(setting)
    local enable = checkNumber(setting.enable)
    if enable == 0 then
        ---禁用
        FuntoyGlobalSettings.UseBloom = false
    else
        FuntoyGlobalSettings.UseBloom = true
        ---标准档的情况下   --- 这个 "NewFuntoyBloomRenderFeature" 已经无效了, 此处的代码不起任何作用;
        local rendererFeature = KTool.GetRenderFeatureActiveByName("NewFuntoyBloomRenderFeature")
        if not isNull(rendererFeature) then
            rendererFeature.settings.MaxIterations = checkNumber(setting.blurIteration)
        end
    end
end

