---ApplyAntialias
---设置抗锯齿
---@param setting table
function XGraphicSetup.ApplyAntialias(setting)
    if Application.platform == CS.UnityEngine.RuntimePlatform.Android then 
        ---泰国版本特殊处理，新玩家默认关闭抗锯齿
        local customGraphicSettings = PlayerPrefsUtility.GetEncryptedString(CUSTOM_SETTING_PREFS)
        if string.isEmpty(customGraphicSettings) then
            setting.enable = 0
        end 
    end

    local openSMAA = false
    if setting.enable == 1 and not XGraphicSetup.IsGLESDevice() and not XGraphicSetup.IsPowerVR() then
        ---开启的
        local quality = checkNumber(setting.quality)
        if Application.platform == RuntimePlatform.WindowsPlayer then
            quality = 8 ---如果是pc编辑器或者是windows player 出来的抗锯齿直接用8倍
        end

        local qualityDevice = XGraphicSetup.GetDefaultQuality()-- default quality
        if Application.platform == CS.UnityEngine.RuntimePlatform.Android then
            if XGraphicSetup.IsSamsung() or XGraphicSetup.IsImmortalis() then 
                quality = 0 
            else
                ---Android 配置
                if qualityDevice ~= XGraphicQuality.Highest then
                    quality = 2 ---如果android上不是最高等级时用2倍抗锯齿
                end
            end 
        elseif Application.platform == CS.UnityEngine.RuntimePlatform.IPhonePlayer then
            if qualityDevice >= XGraphicQuality.High then 
                quality = 4
            else
                quality = 2
            end 
        end

        UniversalRenderPipeline.asset.msaaSampleCount = quality
        --print('---->>>', qualityDevice)
        --if qualityDevice == XGraphicQuality.Highest then
            -- openSMAA = true
        --end
    else
        UniversalRenderPipeline.asset.msaaSampleCount = 0 ---用的系统的抗锯齿 0
    end
    ---只有是高配的情况下开启feature上的搞锯齿
    ---@type FuntoyRenderFeature
    local rendererFeature = KTool.GetRenderFeatureActiveByName("NewFuntoyRenderFeature")
    if not isNull(rendererFeature) then
        --- SMAA 这个功能已经彻底无效了, 但是这个 开关还是在的, 开启关闭它不会起任何作用
        rendererFeature.smaaSettings.OpenSMAA = openSMAA
    end
end

---ApplyFrameRate
---设置帧率
---@param frameRate number
function XGraphicSetup.ApplyFrameRate(frameRate)
    frameRate = checkNumber(frameRate)
    if (Application.platform == CS.UnityEngine.RuntimePlatform.IPhonePlayer or
            Application.platform == CS.UnityEngine.RuntimePlatform.Android or Application.platform == CS.UnityEngine.RuntimePlatform.WindowsPlayer)
            and (not Application.isEditor) then
        
        local minFrameRate = 30
        local maxFrameRate = 60 

        if Application.platform == CS.UnityEngine.RuntimePlatform.Android then 
            --android 限制到45
            maxFrameRate = 45 
        elseif Application.platform == CS.UnityEngine.RuntimePlatform.WindowsPlayer then
            -- Windows Player 指定为 60
            minFrameRate = 60
            maxFrameRate = 60
        end 


        if frameRate < minFrameRate then
            frameRate = minFrameRate
        end
        if frameRate > maxFrameRate then
            frameRate = maxFrameRate
        end
        Application.targetFrameRate = frameRate
    elseif Application.isEditor then 
        --编辑器帧率统一设置为30，考虑到很多协程等待的单位为帧，如果编辑器上帧率比真机上高很多，那么很多体验与真机不同，故将编辑器帧率调到真机水平。
        Application.targetFrameRate = 30
    end
end

---ApplyReflection
function XGraphicSetup.ApplyReflection(graphicLevel)
    if graphicLevel > XGraphicQuality.Middle then 
        FuntoyGlobalSettings.HideReflection = false
    else 
        FuntoyGlobalSettings.HideReflection = true
    end
end 

---SetUp
---启动设置
function XGraphicSetup.SetUp()
    local settingJson = PlayerPrefsUtility.GetEncryptedString(CUSTOM_SETTING_PREFS, '')
    local quality = XGraphicSetup.GetDefaultQuality()
    if string.isEmpty(settingJson) then
        ---获取硬件设置
        ---@type TableML.TableFile
        local tableFile = SettingModule.Get(SettingGraphicPath)
        ---@type TableML.TableFileRow
        local row = tableFile:GetByPrimaryKey(quality)
        local resolutionLevelId = checkNumber(row:Get('resolutionLevel'))
        local graphicLevel = checkNumber(row:Get('graphicLevel'))
        local fpsLevelId = checkNumber(row:Get('fpsLevel'))
        local fxaLevel = checkNumber(row:Get('fxaaLevel'))
        local bloomLevel = checkNumber(row:Get('bloomLevel'))
        local shadowLevel = checkNumber(row:Get('shadowLevel'))
        local lodLevel = checkNumber(row:Get('lodLevel'))
        XGraphicSetup.Apply({ --这边key和配表中保持一致
            shadowLevel = shadowLevel,
            bloomLevel = bloomLevel,
            fxaaLevel = fxaLevel,
            fpsLevel = fpsLevelId,
            graphicLevel = graphicLevel,
            resolutionLevel = resolutionLevelId,
            lodLevel = lodLevel
        })
    else
        -----自定义的配置
        local setting = table.deserialize(settingJson)
        XGraphicSetup.Apply(setting)
    end
    ---获取硬件设置
    if quality <= XGraphicQuality.Low then
        ---如果是低端机，禁用动态骨骼
        isDynamicBoneEnable = false
    end
end

---IsDynamicBoneEnable
---是否动态骨骼启用
function XGraphicSetup.IsDynamicBoneEnable()
    return isDynamicBoneEnable
end

---SetDynamicBoneEnable
---设置是否开启动态骨骼
---@param enable boolean
function XGraphicSetup.SetDynamicBoneEnable(enable)
    if isDynamicBoneEnable then
        CS.DynamicBone.IsEnabled = checkBool(enable)
    else
        CS.DynamicBone.IsEnabled = false
    end
end

function XGraphicSetup.GetDefaultQuality()
    ---获取硬件设置
    local quality = XGraphicQuality.Middle ---初始为中级
    if Application.isEditor or Application.platform == RuntimePlatform.WindowsPlayer then
        quality = XGraphicQuality.Highest
    else
        if Application.platform == CS.UnityEngine.RuntimePlatform.IPhonePlayer then
            ---ios
            quality = MobileHardwareUtils.GetIOSQuality()
        elseif Application.platform == CS.UnityEngine.RuntimePlatform.Android then
            --Android
            quality = MobileHardwareUtils.GetAndroidQuality()
        else
            ---其他平台的设置为最高
            quality = XGraphicQuality.High
        end
    end
    return quality
end

return XGraphicSetup
